SELECT COUNT(*) AS total_attempts
FROM pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT COUNT(*) AS total_attempts
FROM payments.pos_payments
WHERE ts >= '2026-06-01' AND ts < '2026-07-01';

SELECT COUNT(*) FROM store.write_offs 
WHERE reason = 'expired' 
AND date >= '2026-06-01' AND date < '2026-07-01';

SELECT SUM(units_sold) as total_5kg_atta_sold 
FROM store.daily_sales 
WHERE sku = 'ATTA-WW-5KG' AND date >= '2026-06-01' AND date <= '2026-06-30';

SELECT date, sku, forecast_units_per_day 
FROM store.forecasts 
WHERE date = '2026-11-12';

SELECT sku, name, pack, case_kg 
FROM store.products 
WHERE name ILIKE '%atta%' OR pack ILIKE '%5kg%' OR name ILIKE '%flour%';

SELECT sku, name, pack, case_kg 
FROM store.products 
WHERE name ILIKE '%oil%' OR name ILIKE '%dal%' OR pack ILIKE '%oil%' OR pack ILIKE '%dal%';
